WITH flattened AS (SELECT id, host, log_ts, level, latency_ms, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, attr_value) SELECT *, DENSE_RANK() OVER (PARTITION BY host ORDER BY latency_ms DESC NULLS LAST) AS latency_ms_dense_rank, RANK() OVER (ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_rank, NTILE(3) OVER (ORDER BY latency_ms, id, key) AS latency_ms_bucket FROM flattened;
